import net.minecraft.client.Camera;import org.joml.Matrix4f;import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.world.phys.AABB;
public record RenderLevelStageEvent(Stage getStage,Camera getCamera,Matrix4f getModelViewMatrix,PoseStack getPoseStack){public static float partial=.375f;public static boolean frustum=true;public PartialTick getPartialTick(){return new PartialTick();}public static class PartialTick{public float getGameTimeDeltaPartialTick(boolean ignored){return partial;}}public enum Stage{AFTER_PARTICLES,AFTER_ENTITIES}public Frustum getFrustum(){return new Frustum();}public static class Frustum{public boolean isVisible(AABB b){return frustum;}}public Matrix4f getProjectionMatrix(){Matrix4f m=new Matrix4f();m.m[0]=1;m.m[5]=1.7f;m.m[11]=1;m.m[15]=0;return m;}}
